using System.Data;using Microsoft.Data.SqlClient;using PizzaSatinAlmaYonetimi.Web.Data;using PizzaSatinAlmaYonetimi.Web.Models;
namespace PizzaSatinAlmaYonetimi.Web.Services;
public sealed class BildirimService(ISqlConnectionFactory factory):IBildirimService
{
 public async Task<BildirimViewModel>GetirAsync(int uid,CancellationToken ct){await using var c=factory.CreateConnection();await c.OpenAsync(ct);var ids=new List<int>();await using(var idCmd=new SqlCommand("SELECT BildirimID FROM dbo.Bildirimler WHERE KullaniciID=@KullaniciID ORDER BY OlusturmaTarihi DESC, BildirimID DESC",c)){idCmd.Parameters.Add("@KullaniciID",SqlDbType.Int).Value=uid;await using var ir=await idCmd.ExecuteReaderAsync(ct);while(await ir.ReadAsync(ct))ids.Add(ir.GetInt32(0));}await using var cmd=Komut(c,"dbo.sp_KullaniciBildirimleri");cmd.Parameters.Add("@KullaniciID",SqlDbType.Int).Value=uid;await using var r=await cmd.ExecuteReaderAsync(ct);var l=new List<BildirimSatiri>();var i=0;while(await r.ReadAsync(ct)){if(i>=ids.Count)throw new InvalidOperationException("Bildirim kimliği eşleştirilemedi.");l.Add(new(ids[i++],r.GetString("Baslik"),r.GetString("Mesaj"),r.GetString("OkunmaDurumu"),r.GetDateTime("OlusturmaTarihi"),r.IsDBNull("OkunmaTarihi")?null:r.GetDateTime("OkunmaTarihi")));}await r.CloseAsync();await using var say=Komut(c,"dbo.sp_OkunmamisBildirimSayisi");say.Parameters.Add("@KullaniciID",SqlDbType.Int).Value=uid;var count=Convert.ToInt32(await say.ExecuteScalarAsync(ct));return new(){Bildirimler=l,OkunmamisSayisi=count};}
 public Task OkunduYapAsync(int id,int uid,CancellationToken ct)=>Calistir("dbo.sp_BildirimiOkunduYap",uid,ct,id);public Task TumunuOkunduYapAsync(int uid,CancellationToken ct)=>Calistir("dbo.sp_TumBildirimleriOkunduYap",uid,ct,null);
 private async Task Calistir(string ad,int uid,CancellationToken ct,int? id){await using var c=factory.CreateConnection();await c.OpenAsync(ct);await using var cmd=Komut(c,ad);if(id.HasValue)cmd.Parameters.Add("@BildirimID",SqlDbType.Int).Value=id;cmd.Parameters.Add("@KullaniciID",SqlDbType.Int).Value=uid;await cmd.ExecuteNonQueryAsync(ct);}private static SqlCommand Komut(SqlConnection c,string a)=>new(a,c){CommandType=CommandType.StoredProcedure};
}
